#!/usr/bin/env bash
# Generated by the local console for one installation. No credentials included.
set -u
umask 077
capture_root=__SILENCER_DATA_ROOT__
capture_state_root=__SILENCER_CAPTURE_ROOT__
capture_platform=__SILENCER_PLATFORM__
capture_verifier=__SILENCER_VERIFIER__
capture_managed=__SILENCER_MANAGED__
capture_keep_ca=__SILENCER_KEEP_CA__
capture_ca_sha256=__SILENCER_CA_SHA256__
capture_linux_ca_id=__SILENCER_LINUX_CA_ID__
capture_sandbox=''
if [[ $# == 2 && "$1" == --sandbox ]]; then
  capture_sandbox="$(cd "$2" && pwd -P)" || exit 2
  capture_temp_base="$(cd "${TMPDIR:-/tmp}" && pwd -P)"
  case "$capture_sandbox" in /tmp/*|/private/tmp/*|"$capture_temp_base"/*) ;; *) exit 2;; esac
  [[ -f "$capture_sandbox/.silencer-installer-sandbox" && "$(cat "$capture_sandbox/.silencer-installer-sandbox")" == silencer-installer-test-v1 ]] || exit 2
  [[ -z "$(find "$capture_sandbox" -type l -print -quit)" && "$capture_root" == "$capture_sandbox/data" && "$capture_state_root" == "$capture_root/control.json.capture" ]] || exit 2
  capture_system="$(cat "$capture_sandbox/platform")"
elif [[ $# == 0 ]]; then capture_system="$(uname -s)"
else echo 'Unknown uninstaller argument' >&2; exit 2
fi
case "$capture_system" in Darwin) capture_actual=darwin;; Linux) capture_actual=linux;; *) exit 2;; esac
[[ "$capture_actual" == "$capture_platform" && "$capture_root" == /* && "$capture_state_root" == "$capture_root/"* ]] || { echo 'Run this script on its original computer.' >&2; exit 2; }
capture_work="$(mktemp -d "${TMPDIR:-/tmp}/silencer-uninstall.XXXXXX")" || exit 1
capture_service_state=pending
capture_certificate_state=pending
capture_result=1
capture_reason='尚未完成检查 / Verification pending'

# Write pending immediately, so an interrupted retry cannot leave an old
# successful report behind. The final trap also covers Ctrl+C and TERM.
mkdir -p "$capture_state_root" || exit 1
capture_report="$capture_state_root/uninstall-report.html"
capture_label() {
  case "$1" in
    removed) printf '已移除并检查 / Removed and verified';;
    retained) printf '按选择保留 / Retained by choice';;
    not-present) printf '未生成证书 / No CA generated';;
    unmanaged) printf '未登记安装，未操作服务 / Unmanaged; service untouched';;
    failed) printf '需要处理 / Action required';;
    *) printf '尚未完成检查 / Not verified';;
  esac
}
capture_write_report() {
  capture_service_label="$(capture_label "$capture_service_state")"
  capture_certificate_label="$(capture_label "$capture_certificate_state")"
  capture_title='仍有步骤需要处理 / Action required'
  [[ "$capture_service_state" != pending ]] || capture_title='正在检查 / Verification pending'
  [[ "$capture_result" != 0 ]] || capture_title='卸载完成 / Uninstall complete'
cat > "$capture_report" <<HTML
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Silencer 卸载报告 / Uninstall report</title>
<style>body{font:16px/1.8 system-ui;max-width:760px;margin:48px auto;padding:0 24px;color:#172033;background:#f8fafc}main{background:white;border:1px solid #dbe1ea;border-radius:16px;padding:28px}code{background:#edf2f7;padding:3px 6px}li{margin:12px 0}li[data-service],li[data-certificate]{list-style:none;border:1px solid #dbe1ea;border-radius:10px;padding:12px}li[data-service="removed"],li[data-certificate="removed"],li[data-certificate="not-present"]{border-color:#86d5b0;background:#effbf4}li[data-service="failed"],li[data-service="unmanaged"],li[data-certificate="failed"]{border-color:#f3c47b;background:#fff9ed}</style><main>
<h1>Silencer 卸载报告</h1><h2>$capture_title</h2><p>此报告来自脚本的实际检查。网页断开连接本身不代表卸载成功。</p>
<ul><li data-service="$capture_service_state">后台服务 / Service: <strong>$capture_service_label</strong></li><li data-certificate="$capture_certificate_state">证书信任 / CA trust: <strong>$capture_certificate_label</strong></li><li>配置、证书文件、日志、映射及安装缓存已保留；远程处理端数据不受影响。</li></ul>

<p>检查说明 / Details: <strong>$capture_reason</strong></p><h2>仍需处理时</h2><p>查看终端的具体错误，处理后可重复执行同一脚本。系统服务没有成功停止时，脚本不会继续清理证书。</p>
<p>macOS：在“钥匙串访问 → 系统 → 证书”核对下方指纹，打开“信任”，将“使用此证书时”改为“使用系统默认”，关闭详情并完成系统确认。</p>
<p>Ubuntu：仅清理此安装的 silencer 证书文件并运行 update-ca-certificates。应用独立证书库中手动导入的副本，需要在该应用内移除。</p><p>本次 CA SHA-256：<code>$capture_ca_sha256</code></p>
<p>官方 Mitmproxy 网络扩展可能被其他应用共用，脚本保留此共享组件。确认无其他用途后，可在系统“网络扩展”中停用。系统代理、VPN、路由和 DNS 不作修改。</p><details><summary>查看执行详情 / Execution details</summary><pre>
HTML
if [[ -f "$capture_work/operations.log" ]]; then sed -e 's/\&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' "$capture_work/operations.log" >> "$capture_report"; fi
printf '%s\n' '</pre></details></main></html>' >> "$capture_report"
}
capture_write_report
capture_finish() {
  capture_exit=$?
  trap - EXIT
  exec 1>&3 2>&4
  wait "$capture_log_pid" 2>/dev/null || true
  capture_write_report
  printf '\nService: %s\nCA trust: %s\nReport: %s\n' "$capture_service_state" "$capture_certificate_state" "$capture_report"
  if [[ -z "$capture_sandbox" ]]; then
    if [[ "$capture_platform" == darwin ]]; then open "$capture_report" || true; else xdg-open "$capture_report" >/dev/null 2>&1 || true; fi
  fi
  rm -rf -- "$capture_work"
  exit "$capture_exit"
}
exec 3>&1 4>&2
exec > >(tee -a "$capture_work/operations.log") 2>&1
capture_log_pid=$!
trap capture_finish EXIT
trap 'capture_reason="操作已中断，可重新执行脚本 / Interrupted; retry the script"; exit 130' INT
trap 'capture_reason="操作已中断，可重新执行脚本 / Interrupted; retry the script"; exit 143' TERM

capture_check_current_ca() {
  if [[ -f "$capture_state_root/mitmproxy-ca-cert.pem" ]]; then
    [[ -n "$capture_ca_sha256" ]] || { capture_reason='证书已变化，请重新下载脚本 / CA changed; download a fresh script'; return 1; }
    "$capture_verifier" capture-check-ca "$capture_state_root/mitmproxy-ca-cert.pem" "$capture_ca_sha256" identity || { capture_reason='证书身份不匹配，请重新下载脚本 / CA identity changed; download a fresh script'; return 1; }
  fi
}

capture_uninstall_service() {
  # An unmanaged development instance must never remove another installation's
  # user service. The UI explains this before downloading the script.
  [[ "$capture_managed" == true ]] || { capture_service_state=unmanaged; capture_reason='此实例未登记安装，未操作系统服务 / Unmanaged instance; no system service was changed'; return 1; }
  if [[ -f "$capture_root/.silencer-local-install" ]]; then
    [[ "$(cat "$capture_root/.silencer-local-install")" == "$capture_platform" ]] || return 1
    if [[ -n "$capture_sandbox" ]]; then
      : # The embedded installer's own validated sandbox owns service dispatch.
    elif [[ "$capture_platform" == darwin ]]; then
      capture_definition="$HOME/Library/LaunchAgents/com.silencer.local.plist"
      if [[ -f "$capture_definition" ]]; then
        [[ "$(/usr/bin/plutil -extract ProgramArguments.1 raw -o - "$capture_definition")" == "$capture_root/launch.sh" ]] || { capture_reason='系统服务属于另一处安装 / Service belongs to another installation'; return 1; }
      fi
      if launchctl print "gui/$(id -u)/com.silencer.local" > "$capture_work/service.txt" 2>/dev/null; then
        awk -v path="$capture_root/launch.sh" '{ gsub(/^[[:space:]]+|[[:space:]]+$/, ""); if ($0 == path) found=1 } END { exit !found }' "$capture_work/service.txt" || { capture_reason='运行中的服务属于另一处安装 / Running service belongs to another installation'; return 1; }
      fi
    else
      capture_definition="$HOME/.config/systemd/user/silencer-local.service"
      capture_load_state="$(systemctl --user show silencer-local.service -p LoadState --value)" || return 1
      if [[ -f "$capture_definition" || "$capture_load_state" != not-found ]]; then
        capture_exec="$(systemctl --user show silencer-local.service -p ExecStart --value)" || return 1
        # Require the full launcher token, rather than a path prefix.
        printf '%s\n' "$capture_exec" | awk -v path="$capture_root/launch.sh" '{ n=index($0,path); if (n && substr($0,n-1,1) ~ /[ "]/ && substr($0,n+length(path),1) ~ /[ ";]/) found=1 } END { exit !found }' || { capture_reason='系统服务属于另一处安装 / Service belongs to another installation'; return 1; }
      fi
    fi
    capture_reason='后台服务卸载失败，请查看下方执行记录 / Service removal failed; see log'
    printf '%s' '__SILENCER_INSTALLER_BASE64__' | openssl base64 -d -A > "$capture_work/install.sh" || return 1
    # Execute the reviewed, embedded installer; no network download is needed.
    if [[ -n "$capture_sandbox" ]]; then
      /bin/bash "$capture_work/install.sh" --sandbox "$capture_sandbox" --uninstall || return 1
    else
      SILENCER_DATA_DIR="$capture_root" /bin/bash "$capture_work/install.sh" --uninstall || return 1
    fi
  fi
  [[ ! -e "$capture_root/.silencer-local-install" && ! -e "$capture_root/current" && ! -e "$capture_root/launch.sh" ]] || return 1
  if [[ -n "$capture_sandbox" ]]; then
    [[ -z "$(find "$capture_sandbox/services" -type f -print -quit)" ]] || return 1
  elif [[ "$capture_platform" == darwin ]]; then
    [[ ! -e "$HOME/Library/LaunchAgents/com.silencer.local.plist" ]] || return 1
    launchctl list >/dev/null 2>&1 || return 1
    if launchctl print "gui/$(id -u)/com.silencer.local" >/dev/null 2>&1; then return 1; fi
  else
    [[ ! -e "$HOME/.config/systemd/user/silencer-local.service" ]] || return 1
    [[ "$(systemctl --user show silencer-local.service -p LoadState --value 2>/dev/null)" == not-found ]] || return 1
    if systemctl --user is-active --quiet silencer-local.service; then return 1; fi
  fi
  # Also detect orphaned bundle processes. Service registration alone is not a
  # sufficient check when a service manager was forced to terminate the gateway.
  if [[ -z "$capture_sandbox" ]]; then
    capture_processes="$(ps -axo command=)" || return 1
    if printf '%s\n' "$capture_processes" | awk -v root="$capture_root/versions/" 'index($0, root) == 1 { found=1 } END { exit !found }'; then return 1; fi
  fi
  capture_service_state=removed
  capture_reason='后台服务已移除并检查 / Service removed and verified'
}

capture_cleanup_certificate() {
  if [[ "$capture_keep_ca" == true ]]; then capture_certificate_state=retained; return 0; fi
  if [[ -z "$capture_ca_sha256" ]]; then capture_certificate_state=not-present; return 0; fi
  [[ -z "$capture_sandbox" ]] || { capture_reason='隔离测试不允许修改系统信任 / System trust changes are disabled in sandbox'; return 1; }
  [[ "$capture_ca_sha256" =~ ^[A-F0-9]{64}$ && "$capture_linux_ca_id" =~ ^[a-f0-9]{16}$ ]] || return 1
  printf '%s' '__SILENCER_CA_BASE64__' | openssl base64 -d -A > "$capture_work/ca.crt" || return 1
  "$capture_verifier" capture-check-ca "$capture_work/ca.crt" "$capture_ca_sha256" identity || return 1
  capture_reason='证书清理或信任检查失败，请查看下方执行记录 / CA cleanup or verification failed; see log'
  if [[ "$capture_platform" == darwin ]]; then
    capture_trust="$("$capture_verifier" capture-check-ca "$capture_work/ca.crt" "$capture_ca_sha256" trust)" || return 1
    if [[ "$capture_trust" == trusted ]]; then
      /usr/bin/sudo /usr/bin/security remove-trusted-cert -d "$capture_work/ca.crt" || true
      /usr/bin/security remove-trusted-cert "$capture_work/ca.crt" || true
    fi
  else
    capture_destination="/usr/local/share/ca-certificates/silencer-$capture_linux_ca_id.crt"
    if [[ -e "$capture_destination" ]]; then
      [[ ! -L "$capture_destination" ]] || return 1
      "$capture_verifier" capture-check-ca "$capture_destination" "$capture_ca_sha256" identity || return 1
      sudo rm -f -- "$capture_destination" || return 1
    fi
    # Always refresh: a previous attempt may have removed the source file but
    # failed before updating the bundle.
    sudo update-ca-certificates || return 1
  fi
  capture_trust="$("$capture_verifier" capture-check-ca "$capture_work/ca.crt" "$capture_ca_sha256" trust)" || return 1
  [[ "$capture_trust" == untrusted ]] || return 1
  capture_certificate_state=removed
}

capture_service_state=failed
capture_reason='需要 openssl，或本机状态检查未通过 / openssl is required; local checks must pass'
if command -v openssl >/dev/null && capture_check_current_ca && capture_uninstall_service; then
  capture_certificate_state=failed
  if capture_check_current_ca && capture_cleanup_certificate; then capture_result=0; capture_reason='所选卸载操作已完成并检查 / Selected cleanup completed and verified'; fi
fi
exit "$capture_result"
